local PayLockCache = {}

PayHelper = {}

function PayHelper.syncPlayerMoney(userId, data)
    ---@type SBasePlayer
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    local wallet = player.entityPlayerMP:getWallet()
    wallet.m_diamondBlues = data.diamonds or 0
    wallet.m_diamondGolds = data.gDiamonds or 0
    wallet:setGolds(data.golds or 0)
    if type(data.gameCashCoupon) == "table" then
        player.gameCashCoupon = data.gameCashCoupon.balance or 0
    else
        player.gameCashCoupon = data.gameCashCoupon or 0
    end
    player:sendPacket({
        pid = "SyncPlayerMoney",
        diamonds = data.diamonds or 0,
        gDiamonds = data.gDiamonds or 0,
        golds = data.golds or 0,
        gameCashCoupon = player.gameCashCoupon or 0,
    })
    Events.PlayerMoneyChangedEvent:invoke(player, data)
end

local function pay(userId, coinId, request)
    if DBManager:isPlayerLoadFailed(userId) then
        PayLockCache[tostring(request.userId) .. tostring(request.uniqueId)] = nil
        return
    end
    WebService:Pay(userId, request.uniqueId, coinId, request.price, function(data)
        PayLockCache[tostring(request.userId) .. tostring(request.uniqueId)] = nil
        if not data then
            if request.failedCallback then
                request.failedCallback(1)
            end
            LogUtil.logError("pay error, userId=" .. tostring(userId) .. ", uniqueId=" .. tostring(request.uniqueId))
            return
        end
        local player = PlayerManager:getPlayerByUserId(request.userId)
        if not player then
            ---支付成功后，玩家已退出游戏，回滚订单，不需要处理回调
            EngineUtil.disposePlatformOrder(request.userId, data.orderId, false)
            if request.failedCallback then
                request.failedCallback(2)
            end
            return
        end
        PayHelper.syncPlayerMoney(userId, data)
        if type(data.gameCashCoupon) == "table" and data.gameCashCoupon.usage > 0 then
            player:sendPacket({
                pid = "UseGameCashCoupon",
                diamonds = request.price - data.gameCashCoupon.usage,
                gameCashCoupon = data.gameCashCoupon.usage,
            })
        end
        if not request.subKey then
            ---没有绑定数据存储subKey的一律自动消耗订单
            local success, consume = xpcall(function()
                return request.successCallback(player, data.gameCashCoupon.usage)
            end, debug.traceback) ---回调处理，可设置返回值，返回false代表处理(添加物品等)失败，回滚订单，默认是true
            if not success then
                LogUtil.logScriptException(consume)
                consume = false
            end
            if consume == nil then
                consume = true
            end
            if consume then
                GameAnalytics:reportExchangeItems(player, request.uniqueId, coinId, request.price, request.reason, request.goodsCount)
            end
            EngineUtil.disposePlatformOrder(request.userId, data.orderId, consume)
            return
        end
        local success, consume = xpcall(function()
            return request.successCallback(player, data.gameCashCoupon.usage)
        end, debug.traceback) ---回调处理，可设置返回值，返回false代表处理(添加物品等)失败，回滚订单，默认是true
        if not success then
            LogUtil.logScriptException(consume)
            consume = false
        end
        if consume == nil then
            consume = true
        end
        if not consume then
            ---回调处理失败，回滚订单
            EngineUtil.disposePlatformOrder(request.userId, data.orderId, false)
        else
            GameAnalytics:reportExchangeItems(player, request.uniqueId, coinId, request.price, request.reason, request.goodsCount)
            ---保存至缓存，等待数据存储成功后再消耗订单，存储失败会回滚订单
            OrderManager.pushOrderCache({
                userId = tostring(request.userId),
                subKey = tostring(request.subKey),
                orderId = data.orderId
            })
        end
    end)
end

---支付魔方/钻石方法
---@param userId number 玩家Id
---@param uniqueId number|string 商品Id
---@param diamonds number 魔方/钻石数量
---@param successCallback function 支付成功回调函数
---@param failedCallback function 支付失败回调函数
---@param subKey string 绑定的数据存储subKey，设置后会自动检测数据存储成功后消耗订单
function PayHelper.payDiamonds(userId, uniqueId, diamonds, successCallback, failedCallback, subKey, reason, goodsCount)
    uniqueId = tonumber(uniqueId)
    diamonds = tonumber(diamonds)
    local key = tostring(userId) .. tostring(uniqueId)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not diamonds or math.floor(diamonds) ~= diamonds or diamonds < 0 then
        PayLockCache[key] = nil
        return
    end
    if not player then
        PayLockCache[key] = nil
        return
    end
    if player.isKickOut then
        PayLockCache[key] = nil
        return
    end
    if player:getDiamond() + player.gameCashCoupon < diamonds then
        PayLockCache[key] = nil
        return
    end
    if 0 == diamonds then
        PayLockCache[key] = nil
        Events.PayDiamondsSuccessEvent:invoke(userId, uniqueId, diamonds, 0)
        if successCallback then
            return successCallback(player)
        end
        return
    end
    local request = {
        userId = userId,
        uniqueId = uniqueId,
        price = diamonds,
        subKey = subKey,
        successCallback = function(_player, gameCashCoupon)
            ---真实使用的金魔方数量，不含代金卷
            local useDiamonds = math.max(diamonds - gameCashCoupon, 0)
            Events.PayDiamondsSuccessEvent:invoke(userId, uniqueId, diamonds, useDiamonds)
            if successCallback then
                return successCallback(_player, useDiamonds)
            end
        end,
        failedCallback = failedCallback,
        reason = reason,
        goodsCount = goodsCount,
    }
    pay(userId, CurrencyId.GCube, request)
end

---支付魔方/钻石方法(同步方法，带事务机制，购买同一种商品会锁住该商品，等待http返回后才可以再次购买该商品)
---@param userId number 玩家Id
---@param uniqueId number|string 商品Id
---@param diamonds number 魔方/钻石数量
---@param successCallback function 支付成功回调函数
---@param failedCallback function 支付失败回调函数
---@param subKey string 绑定的数据存储subKey，设置后会自动检测数据存储成功后消耗订单
function PayHelper.payDiamondsSync(userId, uniqueId, diamonds, successCallback, failedCallback, subKey, reason, goodsCount)
    local key = tostring(userId) .. tostring(uniqueId)
    if PayLockCache[key] then
        return
    end
    PayLockCache[key] = true
    PayHelper.payDiamonds(userId, uniqueId, diamonds, successCallback, failedCallback, subKey, reason, goodsCount)
end

