---支付绿钞方法
---@param player SBasePlayer 玩家
---@param uniqueId number|string 商品Id
---@param coinId number 绿钞Id
---@param price number 绿钞数量
---@param successCallback function 支付成功回调函数
function PayHelper.payCurrency(player, uniqueId, coinId, price, successCallback, reason, goodsCount)
    if not price or math.floor(price) ~= price or price < 0 then
        return
    end
    if player:getCurrency() < price then
        return
    end
    player:subCurrency(price)
    if successCallback then
        successCallback()
    end
    GameAnalytics:reportExchangeItems(player, uniqueId, coinId, price, reason, goodsCount)
end

function PayHelper.payMoneySync(player, uniqueId, coinId, price, successCallback, failedCallback, subKey, reason, goodsCount)
    if coinId == CurrencyId.GCube or coinId == CurrencyId.Diamonds then
        PayHelper.payDiamondsSync(player.userId, uniqueId, price, successCallback, failedCallback, subKey, reason, goodsCount)
        return
    end
    if coinId == CurrencyId.Golds then
        PayHelper.payGoldsSync(player.userId, uniqueId, price, successCallback, failedCallback, subKey, reason, goodsCount)
        return
    end
    if coinId == CurrencyId.Currency then
        PayHelper.payCurrency(player, uniqueId, coinId, price, successCallback, reason, goodsCount)
        return
    end
end

function PayHelper.payMoney(player, uniqueId, coinId, price, successCallback, failedCallback, subKey, reason, goodsCount)
    if coinId == CurrencyId.GCube or coinId == CurrencyId.Diamonds then
        PayHelper.payDiamonds(player.userId, uniqueId, price, successCallback, failedCallback, subKey, reason, goodsCount)
        return
    end
    if coinId == CurrencyId.Golds then
        PayHelper.payGolds(player.userId, uniqueId, price, successCallback, failedCallback, subKey, reason, goodsCount)
        return
    end
    if coinId == CurrencyId.Currency then
        PayHelper.payCurrency(player, uniqueId, coinId, price, successCallback, reason, goodsCount)
        return
    end
end